import { Data, Effect } from "effect"

export interface Warehouse {
  readonly warehouseId: string
  readonly warehouseName: string
  readonly region: string
}

export class WarehouseNotFound extends Data.TaggedError("WarehouseNotFound")<{
  readonly warehouseName: string
  readonly region: string
}> {}

const warehouses: ReadonlyArray<Warehouse> = [
  {
    warehouseId: "wh_204",
    warehouseName: "North Depot",
    region: "eu-north"
  }
]

export const findWarehouse = Effect.fn("WarehouseDirectory.findWarehouse")(
  function* (warehouseName: string, region: string) {
    const warehouse = warehouses.find(
      (entry) => entry.warehouseName === warehouseName && entry.region === region
    )

    if (!warehouse) {
      return yield* new WarehouseNotFound({ warehouseName, region })
    }

    return warehouse
  }
)

export const describeMissingWarehouse = (error: WarehouseNotFound): string =>
  `Warehouse "${error.warehouseName}" is not registered in ${error.region}`
